      "sidekick": "minsu",
      "xpReward": 150,
      "title": {
        "ko": "휴대폰을 잃어버렸을 때",
        "de": "Wenn du dein Handy verloren hast",
        "en": "When you've lost your phone"
      },
      "intro": {
        "ko": "",
        "de": "Mist: dein Handy ist weg. Du gehst zum Fundbüro der U-Bahn. Wo zuletzt gesehen? Melden und nachfragen.",
        "en": "Ugh: your phone is gone. You go to the subway lost & found. Where last seen? Report it and ask."
      },
      "vocab": [
        {
          "korean": "휴대폰",
          "note": {
            "ko": "",
            "de": "Handy (auch 핸드폰).",
            "en": "cell phone (also 핸드폰)."
          }
        },
        {
          "korean": "잃어버리다",
          "note": {
            "ko": "",
            "de": "verlieren.",
            "en": "to lose."
          }
        },
        {
          "korean": "분실물",
          "note": {
            "ko": "",
            "de": "Fundsache / verlorenes Objekt (분실물 센터 = Fundbüro).",
            "en": "lost item (분실물 센터 = lost & found)."
          }
        },
        {
          "korean": "찾다",
          "note": {
            "ko": "",
            "de": "finden / suchen.",
            "en": "to find / look for."
          }
        },
        {
          "korean": "신고하다",
          "note": {
            "ko": "",
            "de": "melden / Anzeige machen.",
            "en": "to report."
          }
        },
        {
          "korean": "혹시",
          "note": {
            "ko": "",
            "de": "vielleicht / zufällig (höfliche Nachfrage).",
            "en": "by any chance (polite asking)."
          }
        }
      ],
      "grammarIds": [
        "grammar_a2_change"
      ],
      "grammarBlock": {
        "title": {
          "ko": "-아/어 버리다",
          "de": "-아/어 버리다: (versehentlich/leider) ganz …",
          "en": "-아/어 버리다: (regretfully) completely …"
        },
        "explanation": {
          "ko": "",
          "de": "Abgeschlossene Handlung, oft mit Bedauern: Verb-Stamm + -아/어 버리다. 잃다 → 잃어버리다 = '(leider ganz) verlieren'. 잊다 → 잊어버리다 = 'vergessen'.",
          "en": "Completed action, often with regret: verb stem + -아/어 버리다. 잃다 → 잃어버리다 = 'to lose (for good)'. 잊다 → 잊어버리다 = 'to forget'."
        }
      },
      "dialog": [
        {
          "speaker": "user",
          "ko": "저기요, 휴대폰을 잃어버렸어요.",
          "de": "Entschuldigung, ich habe mein Handy verloren.",
          "en": "Excuse me, I lost my phone."
        },
        {
          "speaker": "minsu",
          "ko": "어디에서 잃어버리셨어요?",
          "de": "Wo haben Sie es verloren?",
          "en": "Where did you lose it?"
        },
        {
          "speaker": "user",
          "ko": "지하철에 두고 내린 것 같아요.",
          "de": "Ich glaube, ich hab es in der U-Bahn liegen lassen.",
          "en": "I think I left it on the subway."
        },
        {
          "speaker": "minsu",
          "ko": "분실물 센터에 접수해 드릴게요. 확인해 볼게요.",
          "de": "Ich nehme das fürs Fundbüro auf. Ich schaue mal nach.",
          "en": "I'll file it with the lost & found. Let me check."
        },
        {
          "speaker": "user",
          "ko": "혹시 검은색 휴대폰 들어왔어요?",
          "de": "Ist zufällig ein schwarzes Handy abgegeben worden?",
          "en": "Has a black phone been turned in, by any chance?"
        },
        {
          "speaker": "minsu",
          "ko": "잠시만요, 확인해 볼게요.",
          "de": "Einen Moment, ich schaue nach.",
          "en": "One moment, I'll check."
        }
      ],
      "quests": [
        {
          "type": "hoerverstehen",
          "data": {
            "audioKo": "어디에서 잃어버리셨어요?",
            "options": [
              {
                "de": "Wo haben Sie es verloren?",
                "en": "Where did you lose it?"
              },
              {
                "de": "Welche Farbe hat es?",
                "en": "What color is it?"
              },
              {
                "de": "Wann war das?",
                "en": "When was that?"
              },
              {
                "de": "Haben Sie es gemeldet?",
                "en": "Did you report it?"
              }
            ],
            "correctIndex": 0
          }
        },
        {
          "type": "uebersetzen",
          "data": {
            "promptDe": "Ich habe mein Handy verloren.",
            "promptEn": "I lost my phone.",
            "options": [
              {
                "ko": "휴대폰을 잃어버렸어요."
              },
              {
                "ko": "휴대폰이 없어요."
              },
              {
                "ko": "휴대폰을 샀어요."
              },
              {
                "ko": "휴대폰이 비싸요."
              }
            ],
            "correctIndex": 0
          }
        },
        {
          "type": "particlePop",
          "data": {
            "prefix": "휴대폰",
            "suffix": " 잃어버렸어요.",
            "options": [
              "을",
              "를",
              "이",
              "가",
              "로",
              "에"
            ],
            "correctIndex": 0,
            "explanationDe": "휴대폰 endet auf Konsonant (ㄴ) → Objektpartikel 을.",
            "explanationEn": "휴대폰 ends in a consonant (ㄴ) → object particle 을."
          }
        }
      ],
      "culturalNote": {
        "title": {
          "ko": "분실물 찾기",
          "de": "Fundsachen in Korea",
          "en": "Lost & found in Korea"
        },
        "body": {
          "ko": "",
          "de": "Korea hat eine hohe Fundquote: U-Bahn-Fundbüros (유실물센터) und die App 'LOST112' sammeln Funde. Ein liegen gelassenes Handy taucht erstaunlich oft wieder auf.",
          "en": "Korea has a high recovery rate: subway lost & found offices (유실물센터) and the 'LOST112' app track items. A left-behind phone resurfaces surprisingly often."
        }
      },
      "shelf": "a2_move",
      "backdrop": "directions"
    }

